  "nav.alerts": { tr: "Alarmlar", en: "Alerts", fr: "Alertes" },
  "alerts.title": { tr: "Alarmlar", en: "Alerts", fr: "Alertes" },
  "alerts.description": { tr: "Fiyat eşiği, günlük değişim ve yeni KAP bildirimleri için bu cihaza bildirim gönderilir. Hesap gerekmez; alarmlar bu tarayıcının cihaz anahtarına bağlıdır.", en: "Get notified on this device about price thresholds, daily moves and new KAP disclosures. No account needed: alerts belong to this browser's device key.", fr: "Recevez sur cet appareil des notifications de seuils de prix, de variations journalières et de nouvelles déclarations KAP. Sans compte : les alertes sont liées à la clé de cet appareil." },
  "alerts.delayNote": { tr: "Fiyat alarmları 15 dk gecikmeli fiyatlarla, yalnızca seans saatlerinde (10:00–18:30) değerlendirilir.", en: "Price alerts use 15-minute delayed prices and are checked during the session only (10:00–18:30).", fr: "Les alertes de prix utilisent des cours différés de 15 min et ne sont vérifiées que pendant la séance (10:00–18:30)." },
  "alerts.permissionTitle": { tr: "Bildirim izni", en: "Notification permission", fr: "Autorisation des notifications" },
